import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"MQTT-Client","description":"Transfer selected Home Assistant values live over MQTT and control supported entities.","frontmatter":{"title":"MQTT-Client","description":"Transfer selected Home Assistant values live over MQTT and control supported entities."},"headers":[],"relativePath":"en/projects/mqtt-client/index.md","filePath":"en/projects/mqtt-client/index.md","lastUpdated":1792778683000}'),i={name:"en/projects/mqtt-client/index.md"};function r(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="mqtt-client-0-1-16" tabindex="-1">MQTT-Client 0.1.16 <a class="header-anchor" href="#mqtt-client-0-1-16" aria-label="Permalink to &quot;MQTT-Client 0.1.16&quot;">​</a></h1><p>MQTT-Client sends selected Home Assistant devices, states and attributes to an external MQTT broker, such as ioBroker&#39;s MQTT adapter. Choose the values you need instead of mirroring the entire HA inventory. The existing HA broker remains in place. The app reads HA directly; it is not a broker bridge.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/mqtt_client" target="_blank" rel="noreferrer">Source and configuration reference</a> · <a href="/projects/mqtt-client/">Deutsche Dokumentation</a></p><h2 id="setup-and-selection" tabindex="-1">Setup and selection <a class="header-anchor" href="#setup-and-selection" aria-label="Permalink to &quot;Setup and selection&quot;">​</a></h2><ol><li>Add <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> to the Home Assistant app store.</li><li>Install and start <strong>MQTT-Client</strong>; amd64 and aarch64 are supported.</li><li>Open the web interface and save the external broker&#39;s host, port, username and password. The default port without TLS is 1883.</li><li>Select a device on the left. Its dialog groups entities into control, sensors, configuration and diagnostics. Search also finds entities inside devices.</li><li>Select the states and attributes to transfer. The checkbox on the right of a value row includes the state and all attributes; device-wide selection can include every value of that device.</li></ol><p>Changes apply immediately. No additional HA access token is required: the app uses Supervisor access to the HA Core API. Use different client IDs and topic prefixes for multiple instances.</p><h2 id="live-transfer-and-status" tabindex="-1">Live transfer and status <a class="header-anchor" href="#live-transfer-and-status" aria-label="Permalink to &quot;Live transfer and status&quot;">​</a></h2><p>After a complete initial snapshot, the app processes HA state changes live over WebSocket. Reconnecting to HA loads a fresh snapshot; reconnecting to MQTT republishes all selected values.</p><p>If the live connection fails, the existing polling mechanism remains the fallback: <strong>every five seconds by default</strong>, configurable using <code>poll_interval</code> from 1 to 300 seconds. Changes missed during an outage or between fallback polls cannot be reconstructed. Event queue overload is reported and requests a new synchronization.</p><p>Status separates MQTT connectivity and HA reachability and shows live/polling mode, last synchronization, last publication, publication count and sanitized error types. Credentials and message contents are not exposed there.</p><table tabindex="0"><thead><tr><th>MQTT topic</th><th>Contents</th></tr></thead><tbody><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/state</code></td><td>State as text</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/attribute/&lt;attribute&gt;</code></td><td>Selected attribute</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/set</code></td><td>Return channel for supported commands</td></tr><tr><td><code>&lt;topic_prefix&gt;/availability</code></td><td><code>online</code> after successful HA synchronization, otherwise <code>offline</code></td></tr></tbody></table><p>The default prefix is <code>ha_external</code>. States and attributes use QoS 1 and Retain; no MQTT Discovery is generated. Initial setup publishes states and attributes before subscribing to <code>/set</code> return channels, with a default 50 ms delay between publications. <code>unknown</code> and <code>unavailable</code> pass through; missing entities produce <code>unavailable</code>.</p><h2 id="commands-back-to-ha" tabindex="-1">Commands back to HA <a class="header-anchor" href="#commands-back-to-ha" aria-label="Permalink to &quot;Commands back to HA&quot;">​</a></h2><p>Return channels are enabled automatically for selected controllable entities. Sensors remain outgoing-only. Send commands to the corresponding <code>/set</code> topic <strong>without Retain</strong>.</p><table tabindex="0"><thead><tr><th>Entity</th><th>Payload</th></tr></thead><tbody><tr><td>Toggle-like entity</td><td><code>ON</code> or <code>OFF</code></td></tr><tr><td><code>number</code>, <code>input_number</code></td><td>Numeric value</td></tr><tr><td><code>select</code>, <code>input_select</code></td><td>Available option name</td></tr><tr><td><code>text</code>, <code>input_text</code></td><td>Text</td></tr><tr><td><code>button</code>, <code>input_button</code></td><td><code>PRESS</code></td></tr><tr><td><code>cover</code></td><td><code>OPEN</code>, <code>CLOSE</code>, <code>STOP</code> or <code>{&quot;position&quot;:45}</code></td></tr><tr><td><code>light</code></td><td><code>{&quot;brightness_pct&quot;:75}</code></td></tr><tr><td><code>fan</code></td><td><code>{&quot;percentage&quot;:50}</code></td></tr></tbody></table><p>Each JSON command permits only the named field and a finite number from 0 to 100. The HA device must support the function. Legacy entity-ID topics such as <code>ha_external/switch.plug/set</code> remain valid. Retained commands, stale commands and invalid contents are discarded; arbitrary HA action calls are unsupported.</p><h2 id="remove-obsolete-retained-topics" tabindex="-1">Remove obsolete retained topics <a class="header-anchor" href="#remove-obsolete-retained-topics" aria-label="Permalink to &quot;Remove obsolete retained topics&quot;">​</a></h2><p><strong>Veraltete Retain-Topics prüfen</strong> (review obsolete retained topics) lists recorded topics no longer used after selection, prefix or device name changes. Select topics and confirm removal; at most 100 per operation.</p><p>The app clears only its own acknowledged publications on the currently configured broker. Active and foreign topics are protected. The inventory persists in <code>/data/mqtt-topics.json</code>. Failed removals remain available for retry. There is <strong>no automatic cleanup</strong>. Unrecorded obsolete topics from before this update still require manual broker cleanup.</p><h2 id="back-up-and-restore-settings" tabindex="-1">Back up and restore settings <a class="header-anchor" href="#back-up-and-restore-settings" aria-label="Permalink to &quot;Back up and restore settings&quot;">​</a></h2><p><strong>Einstellungen sichern</strong> (back up settings) downloads JSON containing broker settings, client ID, topic prefix, selection, polling interval, publication delay and custom CA. <strong>Sicherung öffnen</strong> (open backup) validates the file and asks before replacing settings.</p><p>The file contains <strong>no MQTT password, client certificate, private key or HA token</strong>. It is not encrypted. Locally stored credentials and client certificate/key are retained for the same broker. Enter them again when changing to another broker. Retained payloads are excluded; this does not replace a complete HA app backup.</p><h2 id="tls-with-custom-certificates" tabindex="-1">TLS with custom certificates <a class="header-anchor" href="#tls-with-custom-certificates" aria-label="Permalink to &quot;TLS with custom certificates&quot;">​</a></h2><p><strong>Übertragung und TLS</strong> (transfer and TLS) accepts a custom CA, client certificate and private key through PEM file upload or pasted text. Certificate and key must be provided together. Use the broker&#39;s TLS port, often 8883.</p><p>Server certificates and hostnames are always verified using system trust or a custom CA. Blank secret fields keep stored values. To remove them, enable the explicit option <strong>Gespeicherte TLS-Zertifikate und Schlüssel entfernen</strong> (remove stored TLS certificates and keys) and save. Invalid TLS configurations are rejected before changing settings.</p><h2 id="updates-and-compatibility" tabindex="-1">Updates and compatibility <a class="header-anchor" href="#updates-and-compatibility" aria-label="Permalink to &quot;Updates and compatibility&quot;">​</a></h2><p>Existing 0.1.15 settings remain valid: broker credentials, device/attribute selection, client ID, topic prefix, polling interval and publication delay are not rewritten at startup. TLS retains its previous setting; new certificate fields default to empty. Updating does not delete retained data.</p><p>Version 0.1.16 was checked with backend tests, an MQTT broker, a WebSocket counterpart, TLS client certificates, the web interface and Docker startup. Verify the actual HA installation and supported device functions in your own environment.</p>',28)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
